python3 - <<'PY'
import os, subprocess, glob, json

drive='.agents/skills/agent-emulator-debugging/scripts/drive.py'
env=os.environ.copy();
env.update({
  'DRIVE_SESSION_TAG':'nothingness_linux_debug',
  'DRIVE_TARGET':'linux',
  'DRIVE_RUN_LOG':'/tmp/flutter_run_nothingness_linux_debug.log',
  'DRIVE_FLUTTER_FIFO':'/tmp/flutter_input_nothingness_linux_debug',
  'DRIVE_DESKTOP_HOME':'/tmp/nothingness_nothingness_linux_debug',
})

def extract_last_json_obj(s: str):
    s=s.strip();
    candidates=[i for i,ch in enumerate(s) if ch=='{']
    for start in reversed(candidates):
        depth=0
        for j in range(start,len(s)):
            if s[j]=='{': depth+=1
            elif s[j]=='}':
                depth-=1
                if depth==0:
                    chunk=s[start:j+1]
                    try:
                        return json.loads(chunk)
                    except Exception:
                        break
    raise ValueError('no json')

def run(args):
    out=subprocess.check_output([drive]+args, env=env, text=True, stderr=subprocess.STDOUT)
    return extract_last_json_obj(out)

pre=run(['preflight'])
print('type', type(pre))
print(pre.keys())
print(pre)
PY

